{"cmd":"python3 - <<'PY'
from pathlib import Path
import h5py, scipy.io as sio, mat73
base=Path('/app/data')
SPECIAL_MAT73={'data_structure_JEB6_2021-04-18.mat'}
for dname in ['Ephys_Behavior','RandomizedDelay_Ephys_Behavior']:
    for fn in sorted((base/dname).glob('data_structure_*.mat')):
        try:
            if fn.name in SPECIAL_MAT73:
                obj = mat73.loadmat(str(fn))['obj']
                ntrials = int(obj['bp']['Ntrials'])
                counts = [len(p['quality']) for p in obj['clu']]
                loader='mat73'
            else:
                try:
                    with h5py.File(fn,'r') as f:
                        obj=f['obj']
                        bp=obj['bp']
                        if not isinstance(bp,h5py.Group):
                            raise TypeError
                        n = bp['Ntrials'][()]
                        ntrials = int(n.squeeze()) if hasattr(n,'squeeze') else int(n)
                        clu=obj['clu']
                        counts=[int(f[clu[i,0]]['quality'].shape[0]) for i in range(clu.shape[0])]
                        loader='hdf5'
                except OSError:
                    obj=sio.loadmat(fn, simplify_cells=True)['obj']
                    ntrials=int(obj['bp']['Ntrials'])
                    counts=[len(p['quality']) for p in obj['clu']]
                    loader='v5'
            print('OK', dname, fn.name, ntrials, counts, loader)
